function levels(rows, perPage) {
  let count = 1;
  let pages = Math.ceil(rows / perPage);
  while (pages > 1) {
    pages = Math.ceil(pages / perPage);
    count++;
  }
  return count;
}

console.log(levels(500, 500), levels(100000, 500), levels(1e9, 500));

