const keys = [3, 7, 7, 7, 12, 15, 20, 20, 31];

function lowerBound(keys, value) {
  let lo = 0;
  let hi = keys.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (keys[mid] < value) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

console.log(lowerBound(keys, 7), lowerBound(keys, 8), lowerBound(keys, 99));
console.log("in [7, 20):", lowerBound(keys, 20) - lowerBound(keys, 7));

