questions.solution:
const plan = `Hash Join (actual rows=20.00 loops=1)
  Hash Cond: (l.order_id = o.id)
  ->  Seq Scan on order_lines l (actual rows=150000.00 loops=1)
  ->  Hash (actual rows=10.00 loops=1)
        ->  Seq Scan on orders o (actual rows=10.00 loops=1)
              Filter: (customer_id = 42)
              Rows Removed by Filter: 99990`;

function findSeqScans(planText) {
  const result = [];
  let current = null;
  for (const line of planText.split("\n")) {
    const scan = line.match(/Seq Scan on (\w+)/);
    if (scan) {
      current = { table: scan[1], removed: 0 };
      result.push(current);
    } else if (line.includes("->")) {
      current = null;
    } else if (current) {
      const removed = line.match(/Rows Removed by Filter: (\d+)/);
      if (removed) current.removed = Number(removed[1]);
    }
  }
  return result;
}

console.log(findSeqScans(plan));

