const log = [
  "select id from orders where customer_id = 42",
  "select id from orders where customer_id = 7",
  "select id from customers where email = 'ada@example.com'",
  "select id from orders where customer_id = 42",
];

function normalise(sql) {
  let n = 0;
  return sql.replace(/'(?:[^']|'')*'|\b\d+\b/g, () => `$${++n}`);
}

const calls = new Map();
for (const sql of log) {
  const key = normalise(sql);
  calls.set(key, (calls.get(key) ?? 0) + 1);
}
console.log(calls);

