const statusFrequencies = { paid: 0.9, pending: 0.09, cancelled: 0.01 };

function choosePlan(frequencies, value) {
  const fraction = frequencies[value] ?? 0.001;
  return fraction > 0.2 ? "Seq Scan" : "Index Scan";
}

for (const status of ["paid", "pending", "cancelled", "refunded"]) {
  console.log(status, choosePlan(statusFrequencies, status));
}
